// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(0xABCD);

    function setUp() public {
        // deploy contract as deployer so owner() becomes deployer
        vm.prank(deployer);
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        // keep the domain wide; no heavy restrictions
        // Ensure caller is the current owner (deployer)
        vm.prank(deployer);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: reference guarantees owner() != address(0) after a successful transfer
        // and transfer to zero reverts. Therefore: after the call completes successfully (ok == true),
        // owner() MUST NOT be address(0). This holds for the reference for all inputs, but the mutant
        // that removed the zero-address check will make this assertion fail when newOwner == address(0).
        if (ok) {
            assertTrue(c.owner() != address(0));
        } else {
            // if call reverted, then owner must remain the previous owner (deployer)
            assertTrue(c.owner() == deployer);
        }
    }
}

