pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: candidate new owner
    function testFuzz_property(address newOwner) public {
        // admissible domain: keep wide. No need to restrict.

        // initialize contract so Ownable initializer runs and msg.sender becomes owner
        c.initialize();

        // perform the call as the owner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ALL inputs, the reference either reverts (ok==false) or leaves owner() != address(0).
        // The mutant that removed the require can succeed with newOwner==address(0) producing owner()==address(0),
        // so asserting (ok == false) || (c.owner() != address(0)) holds for the reference but fails for the mutant.
        assertTrue(ok == false || c.owner() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(0xABCD);

    function setUp() public {
        vm.prank(deployer);
        c = new C();
        // initialize the contract so Ownable is set up with deployer as owner
        vm.prank(deployer);
        c.initialize();
    }

    // fuzzed parameter: the candidate new owner to transfer to
    function testFuzz_property(address newOwner) public {
        // keep domain wide; allow any address including zero
        // ensure caller is the current owner (deployer) so only transferOwnership path is exercised
        bool ok;
        vm.prank(deployer);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: on the correct contract, whenever transferOwnership returns (ok==true),
        // the resulting owner() must never be address(0). The mutant that removed the require can make
        // owner() == address(0) for some newOwner (i.e., when newOwner == address(0) the call succeeds there).
        // So assert that either the call reverted (ok == false) OR owner() != address(0).
        // The reference satisfies this for all inputs; the mutant fails when it allows a successful call to set owner to zero.
        assertTrue(!ok || c.owner() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: attackerEOA will be the external externally-owned account that originates the tx;
    // intermediaryIsContract is a boolean deciding whether caller is a contract proxy or direct EOA.
    function testFuzz_property(address attackerEOA, bool intermediaryIsContract) public {
        // keep attackerEOA non-zero and different from this test contract to be meaningful
        vm.assume(attackerEOA != address(0));
        vm.assume(attackerEOA != address(this));

        // initialize and set owner to this test contract
        c.initialize();
        // by initialize, owner becomes msg.sender (this test contract)
        address originalOwner = c.owner();
        // sanity: owner should be this test contract
        assertEq(originalOwner, address(this));

        // decide the caller: either attackerEOA calls directly (EOA) or through a deployed ProxyCaller contract
        address caller;
        ProxyCaller proxy;
        if (intermediaryIsContract) {
            proxy = new ProxyCaller();
            caller = address(proxy);
            // set the proxy's forwarder to attackerEOA so that tx.origin will be attackerEOA when proxy makes the call
            proxy.setOriginator(attackerEOA);
        } else {
            caller = attackerEOA;
        }

        // The adversarial scenario: attackerEOA (EOA) will attempt to have "caller" invoke transferOwnership
        // to set new owner to attackerEOA. If transferOwnership checks only msg.sender against owner, then
        // only this test contract (the owner) can succeed; if mutant erroneously checks tx.origin, then a
        // contract caller (with tx.origin == attackerEOA) may pass that check even though msg.sender != owner.

        // fund the attackerEOA so it can pay gas; not strictly necessary but safe
        vm.deal(attackerEOA, 1 ether);

        bool ok;
        if (intermediaryIsContract) {
            // have the proxy perform the call as if it were a separate tx originating from attackerEOA
            vm.prank(attackerEOA);
            try proxy.callTransferOwnership(address(c), attackerEOA) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // direct call from EOA
            vm.prank(attackerEOA);
            try c.transferOwnership(attackerEOA) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // GENERAL ASSERTION: On the reference implementation (which checks msg.sender==owner), only the owner
        // (this test contract) can successfully call transferOwnership. Therefore, for ANY attackerEOA and the
        // intermediary choice, the attempt by a non-owner to transfer ownership must fail. The mutant that uses
        // tx.origin in the onlyOwner modifier will allow the intermediary contract case (intermediaryIsContract==true)
        // when tx.origin==attackerEOA to succeed and thus ok==true for some inputs — causing this assertion to fail.
        assertTrue(!ok);
    }
}

// Minimal helper contract used when routing the call through a contract intermediary.
contract ProxyCaller {
    address public originator;

    // set the intended tx.origin value for tests
    function setOriginator(address who) external {
        originator = who;
    }

    // forwarder: calls transferOwnership on the target
    function callTransferOwnership(address target, address newOwner) external {
        // simply call the target; tx.origin will be the EOA that invoked this (set in vm.prank in the test)
        C(target).transferOwnership(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: an EOA address ownerCandidate and an address newOwnerCandidate
    // We'll deploy a forwarding contract (Caller) that will call transferOwnership on behalf of the EOA.
    // General rule: only the owner (msg.sender == owner()) can call transferOwnership. The mutant that
    // compares tx.origin instead of msg.sender will allow the forwarder call to succeed when tx.origin
    // equals the owner EOA even though msg.sender (the forwarder) is not the owner.
    function testFuzz_property(address ownerCandidate, address newOwnerCandidate) public {
        // keep addresses in wide but valid domain (non-zero new owner), allow ownerCandidate possibly zero to test behavior
        // Do not over-constrain: allow zero ownerCandidate as well (owner() initially is address(0) until initialize),
        // but ensure newOwnerCandidate is not zero so transferOwnership would revert in reference if owner check passes
        if (newOwnerCandidate == address(0)) newOwnerCandidate = address(1);

        // Deploy a forwarder contract that will call c.transferOwnership(newOwnerCandidate)
        Caller forwarder = new Caller(c, newOwnerCandidate);

        // We want to test the scenario where the EOA ownerCandidate is the tx.origin, and the forwarder is msg.sender.
        // Setup: set owner to ownerCandidate by performing initialization flow
        // The contract C uses Initializable and OwnableUpgradeable; calling initialize sets owner to msg.sender.
        // So we impersonate ownerCandidate to call initialize on c to make them the owner.
        // If ownerCandidate is a contract address (has code), we cannot vm.prank it as EOA; ensure it's an EOA by using vm.assume false? Forge fuzzed addresses are EOAs (no code) by default, good.

        // Make ownerCandidate the owner by calling initialize from that EOA
        vm.prank(ownerCandidate);
        c.initialize();

        // Now, simulate the EOA ownerCandidate initiating a transaction that invokes the forwarder contract
        // The forwarder will call c.transferOwnership(newOwnerCandidate). In that transaction the tx.origin == ownerCandidate,
        // but msg.sender inside c will be the address of the forwarder contract.

        // Fund ownerCandidate so it can send the tx to the forwarder if needed
        vm.deal(ownerCandidate, 1 ether);

        // Have ownerCandidate call the forwarder (so tx.origin == ownerCandidate)
        vm.prank(ownerCandidate);
        // call forwarder.trigger() which will in turn call c.transferOwnership
        try forwarder.trigger{value: 0}() {
            // call succeeded
        } catch {
            // ignore revert from the forwarder; we'll check final owner below
        }

        // Exactly one assertion: for the correct contract, transferOwnership must only succeed when msg.sender == owner(),
        // so after the forwarded call (where msg.sender == forwarder != ownerCandidate) the owner must remain ownerCandidate.
        // The mutant that checks tx.origin instead of msg.sender will have changed owner to newOwnerCandidate in some cases,
        // causing this assertion to fail.
        assertTrue(c.owner() == ownerCandidate);
    }
}

// Forwarder contract: receives an EOA call and forwards the transferOwnership call to C
contract Caller {
    C target;
    address newOwner;
    constructor(C _target, address _newOwner) {
        target = _target;
        newOwner = _newOwner;
    }
    // any caller triggers this which will call target.transferOwnership(newOwner)
    function trigger() external {
        // direct external call: msg.sender inside target will be address(this), tx.origin will be original EOA
        target.transferOwnership(newOwner);
    }
}
